"""Verify that rebuilding preserves generated bytes and bounded shared patches."""
from pathlib import Path
import hashlib
import json
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
owned = set(json.loads((HERE/'build_hashes.json').read_text(encoding='utf-8'))['outputs'])
shared = {
    'history/countries/SYR - Syria.txt',
    'common/scripted_effects/IMP_1970_world_politics_effects.txt',
    'common/scripted_effects/mdcw_1970_focus_tree_effects.txt',
    'common/scripted_effects/00_leader_setup_scripted_effects.txt',
    'common/scripted_effects/00_MD_politicsview_scripted_effects.txt',
    'common/scripted_localisation/00_MD_politicsview_scripted_localisation.txt',
}
retirement = json.loads((HERE/'retirement_report.json').read_text(encoding='utf-8'))
shared.update(retirement['retired_foreign_focus_conditions'])
owned.update({'tools/syria_1970/manifest.json', 'tools/syria_1970/build_hashes.json'})


def hashes():
    return {p: hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sorted(owned | shared)}


before = hashes()
subprocess.run([sys.executable, str(HERE/'build_content.py')], cwd=ROOT, check=True)
after = hashes()
changed = [p for p in before if before[p] != after[p]]
result = {'status': 'FAIL' if changed else 'PASS', 'files_checked': len(before), 'changed': changed}
(HERE/'rebuild_validation.json').write_text(json.dumps(result, indent=2)+'\n', encoding='utf-8')
print(json.dumps(result, indent=2))
raise SystemExit(bool(changed))
